import React, { useMemo, useState } from 'react';
import { useKitchenInventory } from '../context/KitchenInventoryContext';

const MENU_SECTIONS = ['All', 'Meals', 'Drinks', 'Smoothies', 'Sauces', 'Sides', 'Desserts', 'Other'];

const normalizeText = (value) => String(value || '').toLowerCase();
const normalizeIngredientCacheKey = (value) => String(value || '').toLowerCase().replace(/\s+/g, ' ').trim();

const getIngredientName = (entry) => {
    if (Array.isArray(entry)) {
        return String(entry?.[2] || entry?.[0] || '').trim();
    }

    if (entry && typeof entry === 'object') {
        return String(entry?.name || '').trim();
    }

    return String(entry || '').trim();
};

const classifyMenuSection = (groupCategory, dishName) => {
    const haystack = `${normalizeText(groupCategory)} ${normalizeText(dishName)}`;

    if (/smoothie|shake|lassi|protein drink/.test(haystack)) return 'Smoothies';
    if (/drink|juice|tea|coffee|latte|cocktail|mocktail|lemonade/.test(haystack)) return 'Drinks';
    if (/sauce|salsa|dressing|dip|chutney|marinade/.test(haystack)) return 'Sauces';
    if (/side|starter|snack|appetizer|fries|rice|beans/.test(haystack)) return 'Sides';
    if (/dessert|cake|cookie|brownie|pudding|ice cream|sweet/.test(haystack)) return 'Desserts';

    return 'Meals';
};

const toMenuItems = (recipeGroups = []) => {
    const flattenedItems = [];

    recipeGroups.forEach((group) => {
        const groupCategory = String(group?.category || '').trim() || 'Other';
        const recipes = Array.isArray(group?.recipes) ? group.recipes : [];

        recipes.forEach((recipe, index) => {
            const dish = String(recipe?.dish || '').trim();
            if (!dish) return;

            const topLevelIngredients = Array.isArray(recipe?.ingredients) ? recipe.ingredients : [];
            const instructionIngredients = Array.isArray(recipe?.instructions)
                ? recipe.instructions.flatMap((instruction) => Array.isArray(instruction?.ingredients) ? instruction.ingredients : [])
                : [];

            const ingredientNames = [...topLevelIngredients, ...instructionIngredients]
                .map((entry) => getIngredientName(entry))
                .map((name) => name.replace(/\s+/g, ' ').trim())
                .filter(Boolean);

            const uniqueIngredients = Array.from(new Set(ingredientNames));

            flattenedItems.push({
                id: `${groupCategory}-${dish}-${index}`,
                dish,
                description: String(recipe?.description || '').trim(),
                groupCategory,
                menuSection: classifyMenuSection(groupCategory, dish),
                ingredients: uniqueIngredients,
            });
        });
    });

    return flattenedItems;
};

const CookMenu = ({ recipes }) => {
    const { getInventoryStateByName } = useKitchenInventory();
    const [selectedSection, setSelectedSection] = useState('All');
    const [showMakeableOnly, setShowMakeableOnly] = useState(true);

    const menuItems = useMemo(() => toMenuItems(recipes), [recipes]);

    const sectionFilteredItems = useMemo(() => {
        if (selectedSection === 'All') {
            return menuItems;
        }

        return menuItems.filter((item) => item.menuSection === selectedSection);
    }, [menuItems, selectedSection]);

    const menuWithAvailability = useMemo(() => {
        const availabilityCache = new Map();

        const isIngredientInStock = (ingredientName) => {
            const cacheKey = normalizeIngredientCacheKey(ingredientName);
            if (!cacheKey) {
                return false;
            }

            if (availabilityCache.has(cacheKey)) {
                return availabilityCache.get(cacheKey);
            }

            const state = getInventoryStateByName(ingredientName);
            const inStock = Boolean(state?.inStock);
            availabilityCache.set(cacheKey, inStock);
            return inStock;
        };

        return sectionFilteredItems.map((item) => {
            const ingredientStatus = item.ingredients.map((ingredientName) => {
                return {
                    name: ingredientName,
                    inStock: isIngredientInStock(ingredientName),
                };
            });

            const missingIngredients = ingredientStatus
                .filter((ingredient) => !ingredient.inStock)
                .map((ingredient) => ingredient.name);

            const requiredCount = ingredientStatus.length;
            const availableCount = requiredCount - missingIngredients.length;
            const isMakeable = requiredCount > 0 && missingIngredients.length === 0;

            return {
                ...item,
                requiredCount,
                availableCount,
                isMakeable,
                missingIngredients,
            };
        });
    }, [sectionFilteredItems, getInventoryStateByName]);

    const filteredItems = useMemo(() => {
        let visible = [...menuWithAvailability];

        if (showMakeableOnly) {
            visible = visible.filter((item) => item.isMakeable);
        }

        return visible.sort((left, right) => {
            if (left.isMakeable !== right.isMakeable) {
                return left.isMakeable ? -1 : 1;
            }

            return left.dish.localeCompare(right.dish);
        });
    }, [menuWithAvailability, showMakeableOnly]);

    const summary = useMemo(() => {
        const total = sectionFilteredItems.length;
        const makeable = menuWithAvailability.filter((item) => item.isMakeable).length;
        return { total, makeable };
    }, [menuWithAvailability, sectionFilteredItems]);

    return (
        <div className='containerDetail bg-lite m-5 color-lite contentLeft'>
            <div className='containerDetail bg-lite color-lite p-10  mb-10'>
                <div className='size25 color-yellow'>Restaurant Menu</div>
                <div className='size15'>
                    {`Ready now: ${summary.makeable}/${summary.total}`}
                </div>
            </div>

            <div className='containerDetail mb-10 flexContainer'>
                {
                    MENU_SECTIONS.map((section) => (
                        <div
                            key={section}
                            type='button'
                            className={`button p-10 mr-5 r-5 flex${MENU_SECTIONS.length}Column ${selectedSection === section ? 'bg-blue color-lite' : 'bg-lite color-lite'}`}
                            onClick={() => setSelectedSection(section)}
                        >
                            {section}
                        </div>
                    ))
                }
                <div
                    type='button'
                    className={`containerDetail button ${showMakeableOnly ? 'bg-green color-lite' : 'bg-lite color-lite'}`}
                    onClick={() => setShowMakeableOnly((prev) => !prev)}
                >
                    {showMakeableOnly ? 'Showing Makeable Only' : 'Show Makeable Only'}
                </div>
            </div>

            {
                filteredItems.length === 0
                    ? <div className='containerDetail bg-lite p-15  size15'>
                        No menu items match this filter.
                    </div>
                    : <div className='containerDetail' style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
                        {
                            filteredItems.map((item) => (
                                <div key={item.id} className='containerDetail bg-veryLite width-100-percent'>
                                    <div className='containerDetail p-10' style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
                                        <div>
                                            <div className='size20 color-yellow'>{item.dish}</div>
                                            <div className='size12 color-mediumDark'>{`${item.menuSection} • ${item.groupCategory}`}</div>
                                        </div>
                                        <div className={`size12 ${item.isMakeable ? 'color-green' : 'color-red'}`}>
                                            {item.isMakeable ? 'Make Now' : `Missing ${item.missingIngredients.length}`}
                                        </div>
                                    </div>

                                    {
                                        item.description
                                            ? <div className='containerDetail size15 p-10 mt-5 mb-5 color-lite bg-lite'>{item.description}</div>
                                            : null
                                    }

                                    <div className='size13 p-10 color-mediumDark mb-5'>
                                        {`Ingredients in stock: ${item.availableCount}/${item.requiredCount}`}
                                    </div>

                                    {
                                        item.missingIngredients.length > 0
                                            ? <div className='size12 color-red p-10'>
                                                {`Missing: ${item.missingIngredients.join(', ')}`}
                                            </div>
                                            : <div className='size12 color-green'>All required ingredients are in stock.</div>
                                    }
                                </div>
                            ))
                        }
                    </div>
            }
        </div>
    );
};

export default React.memo(CookMenu);
